    );
  }

  const binaryPropertyName =
    binaryKeys[0];

  const buffer =
    await this.helpers.getBinaryDataBuffer(
      i,
      binaryPropertyName
    );

  const text =
    buffer.toString("utf8");

  let record;

  try {
    record = JSON.parse(text);
  } catch (error) {
    throw new Error(
      `Raw case item ${i} is invalid JSON: ${error.message}`
    );
  }

  if (!record.googleDoc) {
    throw new Error(
