    Number(metrics.unresolved ?? 0) > 0 ||
    Number(metrics.issues ?? 0) > 0 ||
    Number(metrics.unsatisfiedRules ?? 0) > 0 ||
    Number(metrics.unknownFields ?? 0) > 0;

